use serde::{Deserialize, Serialize};
use std::path::Path;
use crate::error::CoreError;
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum FileFormat { Txt, Csv, Tsv, Markdown, Html, Pdf, Xlsx, Xls, Docx, Pptx, Png, Jpeg, Webp, Gif, Bmp, Tiff }
impl FileFormat { pub fn from_path(p:&Path)->Result<Self,CoreError>{ let e=p.extension().and_then(|x|x.to_str()).unwrap_or("").to_ascii_lowercase(); match e.as_str(){"txt"=>Ok(Self::Txt),"csv"=>Ok(Self::Csv),"tsv"=>Ok(Self::Tsv),"md"|"markdown"=>Ok(Self::Markdown),"html"|"htm"=>Ok(Self::Html),"pdf"=>Ok(Self::Pdf),"xlsx"=>Ok(Self::Xlsx),"xls"=>Ok(Self::Xls),"docx"=>Ok(Self::Docx),"pptx"=>Ok(Self::Pptx),"png"=>Ok(Self::Png),"jpg"|"jpeg"=>Ok(Self::Jpeg),"webp"=>Ok(Self::Webp),"gif"=>Ok(Self::Gif),"bmp"=>Ok(Self::Bmp),"tif"|"tiff"=>Ok(Self::Tiff),_=>Err(CoreError::UnsupportedFormat(e))}} pub fn extension(self)->&'static str{match self{Self::Txt=>"txt",Self::Csv=>"csv",Self::Tsv=>"tsv",Self::Markdown=>"md",Self::Html=>"html",Self::Pdf=>"pdf",Self::Xlsx=>"xlsx",Self::Xls=>"xls",Self::Docx=>"docx",Self::Pptx=>"pptx",Self::Png=>"png",Self::Jpeg=>"jpg",Self::Webp=>"webp",Self::Gif=>"gif",Self::Bmp=>"bmp",Self::Tiff=>"tiff"}}}
